using System;using System.Collections.Generic;using System.Linq;
namespace DoomSNESed {
    // IDs are BSN instruments, not BRR wave numbers. Several drum instruments
    // share a wave and different melodic instruments can use neighbouring waves.
    // Roles and notes checked against retail SPC execution and DOOM MUS scores.
    public static class NativeVoicing {
        // These GM sounds have a known retail counterpart even when the
        // closest overall bank lacks it. MusicLibrary packs that sample in.
        public static int RequiredPatch(MusicNote n){if(n.Channel==9){if(n.Key==75||n.Key==76||n.Key==77)return 56;if(new[]{41,43,45,47,48,50}.Contains(n.Key))return 43;}else{if(n.Program==117)return 43;if(n.Program==47)return 67;}return 0;}
        public static string DrumName(int key){switch(key){case 75:return "Claves";case 76:return "High woodblock";case 77:return "Low woodblock";case 41:return "Low floor tom";case 43:return "High floor tom";case 45:return "Low tom";case 47:return "Low-mid tom";case 48:return "High-mid tom";case 50:return "High tom";default:return "GM drum note "+key;}}
        public static bool Percussion(int id){return id==41||id==42||id==43||id==46||id==47||id==48||id==49||id==50||id==56||id==98;}
        public static string Name(int id){switch(id){case 41:return "Crash cymbal";case 42:return "Snare";case 43:return "Toms";case 44:return "Guitar";case 45:return "Bass";case 46:return "Kick drum";case 47:return "Closed hi-hat";case 48:return "Pedal hi-hat";case 49:return "Open hi-hat";case 50:return "Ride cymbal";case 51:return "Lead guitar";case 52:case 57:case 61:case 88:return "Strings";case 53:case 58:return "Synth bass";case 54:case 92:return "Synth lead";case 56:return "Claves (E1M2) / woodblock";case 59:case 73:case 89:return "Choir / pad";case 60:case 65:case 95:return "Brass";case 66:return "Kalimba / woodblock";case 67:return "Timpani";case 68:case 70:case 90:return "Mallet / bell";case 72:case 78:case 97:return "Strings / violin";case 98:return "Percussion accent";case 55:return "Sustained synth tone (approx.)";case 62:return "Low strings / bass pad (approx.)";case 63:return "Pitch-swept strings effect (approx.)";case 64:return "Layered strings (approx.)";case 69:return "Low timpani / orchestral hit (approx.)";case 71:return "Metallic effect (uncertain)";case 74:return "Synth drum / string effect (approx.)";case 75:case 76:return "Choir layer (approx.)";case 77:return "Low synth / guitar lead (approx.)";case 79:return "Whistle / lead (approx.)";case 80:return "Synth effect (uncertain)";case 81:return "Square synth lead (approx.)";case 82:return "Synth echo / effect (approx.)";case 83:return "Lead harmony (approx.)";case 85:return "Synth lead layer (approx.)";case 86:return "Pizzicato / plucked strings (approx.)";case 87:return "Choir effect (uncertain)";case 91:return "Synth lead layer (approx.)";case 93:return "Low synth bass (approx.)";case 94:return "Guitar harmonics (approx.)";case 96:return "Overdriven guitar variant (approx.)";default:return "Unidentified native tone "+id;}}
        public static int[] Preferred(MusicNote n){if(n.Channel==9){int k=n.Key;if(k==35||k==36)return new[]{46};if(k==38||k==40||k==37||k==39)return new[]{42};if(k==42)return new[]{47,48,49};if(k==44)return new[]{48,47,49};if(k==46)return new[]{49,47,48};if(new[]{41,43,45,47,48,50}.Contains(k))return new[]{43,42};if(k==51||k==53||k==59)return new[]{50,41,49};if(k==75||k==76||k==77)return new[]{56,98,43};return new[]{41,50,49,47};}int p=n.Program;if(p>=32&&p<40)return p>=36?new[]{58,53,45,62}:new[]{45,58,53,62};if(p>=24&&p<32)return new[]{44,51,96,77};if(p==47)return new[]{67,69};if(p==117)return new[]{43};if(p>=40&&p<52)return new[]{61,57,52,72,88,78};if(p>=52&&p<56||p>=88&&p<104)return new[]{73,59,89,61};if(p>=56&&p<64)return new[]{60,65,95,61};if(p>=80&&p<88)return new[]{92,54,44,51};if(p>=8&&p<16||p==108||p>=112&&p<120)return new[]{68,70,66,90,67};return new[]{61,72,44,73,54};}
        public static int Closest(NativeMusicBank bank,MusicNote n){var choices=bank.Instruments.Where(i=>Percussion(i.Id)==(n.Channel==9)||(n.Channel!=9&&n.Program==117&&i.Id==43)).ToArray();Bin.Require(choices.Length>0,"This bank has no "+(n.Channel==9?"percussion":"melodic instruments")+". Choose a different bank.");foreach(int id in Preferred(n))if(choices.Any(i=>i.Id==id))return id;return choices.OrderBy(i=>i.Id).First().Id;}
        public static int Penalty(NativeMusicBank bank,MusicNote note){int[] ids=Preferred(note);for(int i=0;i<ids.Length;i++)if(bank.Instruments.Any(n=>n.Id==ids[i]))return i;return 20;}
        public static int Pitch(MusicNote note,int patch){if(patch==43&&(note.Channel==9||note.Program==117))return Math.Max(0,Math.Min(127,note.Key+24));if(note.Channel!=9)return note.Key;switch(patch){case 46:return note.Key==35?35:36;case 42:return note.Key==38?73:75;case 47:return 68;case 48:return 69;case 49:return 70;case 41:return note.Key==49?62:65;case 43:return Math.Max(60,Math.Min(84,note.Key+24));case 50:return note.Key==53?62:note.Key==59?64:60;case 56:return 67;case 98:return 66;default:return 60;}}
    }
}


